INSERT INTO public.heal_event (id, retailer_id, collector_id, field_name, symptom, heal_prompt, rows_before, rows_after, detected_at, healed_at) VALUES
	(1, 1, 'c_msx1nhwk2akso0fxfx', NULL, 'results array came back empty on every row from the newly created collector', 'results is empty on every row — fields need to be flat top-level, not nested under a results key', 0, 77, '2026-08-19 03:52:15.919975+00', '2026-08-19 03:52:15.717+00'),
	(2, 1, 'c_msx1nhwk2akso0fxfx', NULL, 'search box was not filtering — a Metformin search returned ~1450 unrelated rows instead of the ~77 matching rows', 'the search box is not filtering results — it returns the entire product list regardless of the search term instead of only matching rows', 1450, 77, '2026-08-19 03:52:16.529824+00', '2026-08-19 03:52:16.328+00'),
	(3, 9, 'c_mszko0ud1xsm59ukxx', NULL, 'AI-generated apollo-product collector only extracted product_name and availability_status (2 of 7 target fields) on the first pass; a first heal attempt reported done but did not add the missing fields on re-run', 'product_name and availability_status extract correctly but composition, manufacturer, mrp, selling_price, and pack_size are still completely missing from the output — add explicit extraction fields: composition (string), manufacturer (string), mrp (number), selling_price (number), pack_size (string), as top-level keys in every output row', 2, 7, '2026-08-19 04:14:28.489848+00', '2026-08-19 04:14:28.276+00');
